// --- Detect: stack(s) + repo layout (drives every later phase) ----------
phase('Detect')
const detection = await detectStacks(
  `Detect the project's technology stack and repository layout so the rest of the pipeline can adapt. Use Bash to probe — do not assume.

${repoHints ? `Caller hints (repo roots): ${JSON.stringify(repoHints)}` : 'No repo hints — probe the current directory and the directories inside it.'}

For the current working directory AND any hinted/sibling repo roots, detect each as one repo with a role and stack. Match against this stack catalog (record the matched stack key, its specialistAgent, gateCommands whose tool is actually installed, and conventions):
${stackCatalog()}
For a frontend stack with a devUrl, set devUrl from the dev script port if discoverable. For each repo whose stack lists package managers, set packageManager from its lockfile. ${e2eGlobsLine()}.
When there is a separate backend and frontend repo, set contractSync: installed=true when the contract-sync checker exists (scripts/contract-sync.mjs in either repo, or a project script or task named contract-sync / contract:sync), with the command to run it (node scripts/contract-sync.mjs, or the template command that runs a contract-sync / contract:sync script, as listed for the other stack) and the repo path it runs in.

Always include the actual debug-statement scan as a gate, using the matched stack's debug patterns (grep for those tokens outside tests).
For EACH repo, check git status: run \`git -C <path> rev-parse --is-inside-work-tree\` and \`git -C <path> ls-files | head -1\`. Set tracked=true only when the repo is a git work tree WITH committed files. If a "repo" is an untracked/WIP directory (no .git, or no tracked files — e.g. a scratch frontend that was never committed), set tracked=false and add a warning like "frontend at <path> is untracked WIP — unverified deploy target". Never silently treat a WIP tree as the production target.
Set crossRepo=true when backend and frontend live in different repo roots. Return one entry per detected repo with its path.

${stackDiscoveryPrompt()}`,
  { phase: 'Detect', schema: PROJECT_SCHEMA, agentType: 'code-explorer', ...MODELS.detect }
)

const project = detection.project
const { list: repos, stackOverlay, untrusted: untrustedManifests } = resolveDetect(project, { failure: detection.failure, roots: repoHints })
const crossRepo = !!(project && project.crossRepo) || repos.length > 1
const frontendRepo = repos.find(isFrontendRepo)
const primaryRepo = repos.find((r) => r.role === 'backend' || r.role === 'fullstack') || repos[0]
const stackConventions = Array.from(new Set(repos.flatMap((r) => r.conventions || [])))
const devUrl = resolveDevUrl(devUrlHint, repos)
const hinted = normalizeRepoHints(repoHints)
const frontends = frontendTargets(repos, hinted.entries, devUrlHint)
const runError = hinted.error || frontends.error
if (runError) {
  log(runError)
  return { error: runError }
}
const frontendPasses = frontendPassesLine(frontends.targets)
const backendRepo = repos.find((r) => r.role === 'backend')
// The checker runs only with an allowlisted command (contractSyncCommandFor) in one of the two detected repos.
const contractSync = backendRepo && frontendRepo && backendRepo.path !== frontendRepo.path && project && project.contractSync && project.contractSync.installed
  ? {
      command: contractSyncCommandFor(project.contractSync.command),
      repo: [backendRepo.path, frontendRepo.path].includes(project.contractSync.repo) ? project.contractSync.repo : frontendRepo.path,
    }
  : null
const e2eSkip = frontendRepo ? e2eSkipFor(frontendRepo, e2eArg, !!frontendRepo.e2eConfig) : null
if (contractSync && contractSync.command) log(`Detect: contract-sync installed — runs as a gate (${contractSync.command} in ${contractSync.repo})`)
log(`Detect: ${repos.map((r) => `${r.role}:${r.stack}@${r.path}`).join(', ')}${crossRepo ? ' (cross-repo)' : ''}`)
const repoWarnings = repos.flatMap((r) => (r.warnings || []).concat(r.tracked === false ? [`${r.role} repo "${r.path}" is untracked/WIP — unverified deploy target`] : []))
if (repoWarnings.length) repoWarnings.forEach((w) => log(`⚠ ${w}`))

function repoForStack(stack) {
  if (!stack) return primaryRepo
  return repos.find((r) => r.stack === stack) || primaryRepo
}
function agentForStack(stack) {
  return STACK_AGENT[stack] || STACK_AGENT[(primaryRepo && primaryRepo.stack)] || 'general-purpose'
}
function gateInstructionsFor(repo) {
  const cmds = (repo.gateCommands || []).map((g) => `- ${g.name}: ${g.command}`).join('\n')
  return `Run the detected quality gates for the ${repo.role} repo (${repo.stack}) located at "${repo.path}". cd into it first.
Gates to run (run each; if its tool is genuinely absent mark status "skip"; if the tool exists but cannot run — missing deps, broken env — mark status "unreachable", NEVER "pass"):
${cmds || noGatesLine(repo)}
- Debug scan: grep for stray ${debugScanFor(repo.stack)} in ${sourceDirsFor(repo.stack)} (exclude tests) -> fail if found.${buildGateGuardFor(repo, gateDevUrlFor(repo, frontends.targets, devUrl || 'the dev server URL'))}
Report each gate as pass/fail/skip/unreachable with failing output captured in details. Set allPassed=true only if every gate is pass or skip. Set repo="${repo.path}". Do not fix anything here.`
}

let investigation = null
let invFiles = []
let invConventions = stackConventions
let invRisks = []
let docsToUpdate = []
let existingImpl = []
let brokenLinks = []
let userJourney = null
let tasks = []
let specId = null
let specFolder = null
let acceptanceCriteria = []
let mustNotChange = []
// Quality attributes (NFR-n) are traced like ACs: built against, audited, accepted, and shown in the PR.
let nfrs = []
// A refactor spec builds green-first: characterization tests pass on today's code, then nothing goes red.
let specType = 'feature'
// Backlog slice (SL-nn) this spec builds; marked shipped in backlog.md when the spec is done.
let slice = null
// First unchecked owner Gate: task, and the open task ids at or after it, which this run never builds.
let awaitingOwner = null
let ownerGateId = null
let ownerCut = []
let specMaxTaskId = 0

if (specRef) {
  // --- Execute an existing spec -----------------------------------------
  phase('Spec')
  const loaded = await runAgent(
    `Load the existing specification "${specRef}" so it can be executed.
1. Resolve the reference to ONE folder under .ai/specs/. Accept: a full folder name or path; a legacy numeric id ("0042", "spec-0042", "14" → folders spec-0042-* or 14-*, leading zeros ignored); a ticket key ("PROJ-123" → spec-PROJ-123-*, case-insensitive); a timestamp id ("20261018-1430" → spec-20261018-1430-*). E.g.:
   REF="${specRef}"; REF="\${REF#.ai/specs/}"; REF="\${REF%/}"; KEY="\${REF#spec-}"
   [ -d ".ai/specs/$REF" ] || { echo "$KEY" | grep -qE '^[0-9]+$' && ls -d .ai/specs/*/ | grep -E "/(spec-)?0*$((10#$KEY))-" || ls -d .ai/specs/*/ | grep -iE "/(spec-)?$KEY-"; }
   No match → return empty tasks. Several matches → return them in candidates with empty tasks (do not guess).
2. Read spec-lite.md: frontmatter status (legacy specs without frontmatter → status "legacy"), type (feature | bug | improvement | refactor; empty when absent) and slice (the backlog slice id, empty when absent), unchecked items under "Open questions", the acceptance criteria (keep AC ids), the "Must NOT change" items (keep MNC ids), the "Quality attributes" rows as nfrs ("NFR-n: <attribute>: <requirement>", keep NFR ids; empty when the section is absent), architecture approach and conventions.
3. Read tasks.md, parse the ordered tasks: integer id, title, any "Verify:" criterion, a stack tag if present, the "Covers:" ids, and done=true when checked [x].
4. Return tasksMd: the full text of tasks.md exactly as read, every line unchanged and nothing summarized. Owner gates (tasks titled "Gate: ...") are decided from it by the workflow; never tick, skip or reorder one.
5. If status is "approved" and there are pending tasks, set the frontmatter status to "in-progress" (edit only that line). Leave any other status untouched.
Return specId (the folder name), the relative specFolder, tasksMd, status (as read, before your edit), type, openQuestions, acceptanceCriteria, mustNotChange, nfrs, conventions, and the not-yet-done tasks.`,
    { phase: 'Spec', schema: SPEC_LOAD_SCHEMA, agentType: 'code-explorer', ...MODELS.spec }
  )
  if (loaded && (loaded.candidates || []).length > 1) {
    log(`Spec reference "${specRef}" is ambiguous: ${loaded.candidates.join(', ')}`)
    return { specRef, error: 'ambiguous spec reference — pass the full folder name', candidates: loaded.candidates }
  }
  if (!loaded || !(loaded.tasks || []).length) {
    const idle = loaded ? ownerGateCut(loaded.tasksMd, []) : null
    if (idle && idle.ok && idle.gate) {
      log(`awaiting owner: ${idle.gate.title}`)
      return { specRef, specId: loaded.specId, error: `awaiting owner: ${idle.gate.title}`, awaitingOwner: idle.gate.title, notBuilt: idle.cut }
    }
    log(`No executable tasks found for spec "${specRef}".`)
    return { specRef, error: 'spec not found or all tasks complete' }
  }
  // Only the owner checks a Gate: task; nothing at or after the first unchecked one is built.
  const gateCut = ownerGateCut(loaded.tasksMd, loaded.tasks.filter((t) => !t.done))
  if (!gateCut.ok) {
    log(`Owner-gate check could not run: ${gateCut.reason}. Stopping before any build.`)
    return { specRef, specId: loaded.specId, error: `owner-gate check could not run: ${gateCut.reason}` }
  }
  if (gateCut.gate) {
    awaitingOwner = gateCut.gate.title
    ownerGateId = gateCut.gate.id
    log(`awaiting owner: ${awaitingOwner} (not built: ${gateCut.cut.join(', ')})`)
  }
  if (!gateCut.build.length) {
    const error = gateCut.gate ? `awaiting owner: ${gateCut.gate.title}` : 'spec not found or all tasks complete'
    return { specRef, specId: loaded.specId, error, awaitingOwner, notBuilt: gateCut.cut }
  }
  // Human approval is the gate between spec and build; /sdd records it in the frontmatter.
  if (loaded.status === 'draft' && !allowDraft) {
    log(`Spec ${loaded.specId} is still draft${(loaded.openQuestions || []).length ? ` with ${loaded.openQuestions.length} open question(s)` : ''} — approve it via /sdd first (or pass allowDraft: true).`)
    return { specRef, specId: loaded.specId, error: 'spec not approved', status: 'draft', openQuestions: loaded.openQuestions || [] }
  }
  acceptanceCriteria = loaded.acceptanceCriteria || []
  mustNotChange = loaded.mustNotChange || []
  nfrs = loaded.nfrs || []
  specType = String(loaded.type || 'feature').trim().toLowerCase()
  specId = loaded.specId
  specFolder = loaded.specFolder
  slice = loaded.slice || null
  if ((loaded.conventions || []).length) invConventions = loaded.conventions
  tasks = gateCut.build
  ownerCut = gateCut.cut
  specMaxTaskId = gateCut.maxId
  log(`Loaded spec ${specId} (${specFolder}): ${tasks.length} task(s) to build`)
} else {
  // --- Investigate (per repo when cross-repo) ---------------------------
  phase('Investigate')
  const investigatePrompt = (repo) =>
    `Think deeply and investigate the ${repo.role} repo (${repo.stack}) at "${repo.path}" before any code is written. cd there. Goal: a precise map of where this feature lives and what it must not break.
Feature: ${feature}

1. Locate the files, modules, routes, services, components, DTOs, and tests this feature will touch or depend on.
2. Identify the conventions it must follow${(repo.conventions || []).length ? `: ${repo.conventions.join(', ')}` : ''}.
3. Find EVERY existing doc that describes behavior this feature will change (READMEs, docs/, API contracts, schema docs, CLAUDE.md, OpenAPI). Each => a docsToUpdate entry with the reason.
4. Surface risks, hidden coupling, open questions.
5. EXISTING IMPLEMENTATION — before assuming anything must be built, check what already exists for THIS feature. Search routes, controllers, services, components AND recent git history (\`git -C "${repo.path}" log --oneline -20\`, \`git grep\`). For each piece set status complete/partial/missing with the file path and evidence (e.g. "route already committed in <sha>"). The spec must NOT rebuild 'complete' pieces.
6. USER JOURNEY — trace the reported scenario end-to-end as a real user/request would hit it. List entryPoints (the exact URLs/routes/actions the user starts from), the expectedEndState (what success looks like), and brokenLinks: every target the journey depends on (a route, page, redirect destination, link, API the frontend calls) that does NOT currently resolve. A feature that decodes a link then redirects to a page that 404s is NOT done — record that page as a brokenLink.
7. PRODUCT BRIEF — look for product-brief.md in "${repo.path}", its parent folder, and the current directory. If one exists, read it and the backlog.md next to it and return brief: path, status and owner from its frontmatter, slice = the backlog slice id (SL-nn) whose outcome this feature is (empty if none matches), and rules = every BR the feature must enforce, as "BR-nn: <rule text>" (the slice's cited BRs plus any other rule it touches; skip retired rules). No brief → omit brief.
Read the actual code and docs. Tag each relevant file with its repo path.`

  const investigations = crossRepo
    ? (await parallel(repos.map((r) => () => runAgent(investigatePrompt(r), { phase: 'Investigate', label: `investigate:${r.role}`, schema: INVESTIGATION_SCHEMA, agentType: 'code-explorer', ...MODELS.investigate })))).filter(Boolean)
    : [await runAgent(investigatePrompt(primaryRepo), { phase: 'Investigate', schema: INVESTIGATION_SCHEMA, agentType: 'code-explorer', ...MODELS.investigate })].filter(Boolean)

  investigation = {
    relevantFiles: investigations.flatMap((i) => i.relevantFiles || []),
    conventions: Array.from(new Set([...stackConventions, ...investigations.flatMap((i) => i.conventions || [])])),
    docsToUpdate: investigations.flatMap((i) => i.docsToUpdate || []),
    risks: investigations.flatMap((i) => i.risks || []),
    existingImplementation: investigations.flatMap((i) => i.existingImplementation || []),
    brokenLinks: investigations.flatMap((i) => (i.userJourney && i.userJourney.brokenLinks) || []),
    userJourney: {
      entryPoints: investigations.flatMap((i) => (i.userJourney && i.userJourney.entryPoints) || []),
      expectedEndState: investigations.map((i) => i.userJourney && i.userJourney.expectedEndState).filter(Boolean).join(' / '),
    },
  }
  invFiles = investigation.relevantFiles
  invConventions = investigation.conventions
  invRisks = investigation.risks
  docsToUpdate = investigation.docsToUpdate
  existingImpl = investigation.existingImplementation
  brokenLinks = investigation.brokenLinks
  userJourney = investigation.userJourney
  const brief = investigations.map((i) => i.brief).find((b) => b && b.path) || null
  const briefRules = (brief && brief.rules) || []
  // Rules in a brief nobody has validated yet are assumptions, not requirements.
  const briefDraft = !!(brief && brief.status !== 'validated')
  slice = (brief && brief.slice) || null
  if (brief) log(`Brief: ${brief.path} (${brief.status || 'no status'})${slice ? `, slice ${slice}` : ''}, ${briefRules.length} rule(s)`)
  const alreadyDone = existingImpl.filter((e) => e.status === 'complete').length
  log(`Investigate: ${invFiles.length} relevant file(s), ${invConventions.length} convention(s), ${docsToUpdate.length} doc(s) flagged${alreadyDone ? `, ${alreadyDone} piece(s) already shipped` : ''}${brokenLinks.length ? `, ${brokenLinks.length} broken link(s) in journey` : ''}`)
  if (brokenLinks.length) brokenLinks.forEach((b) => log(`⚠ broken link: ${b.target} — ${b.reason}`))

  // --- Spec: decompose + persist ----------------------------------------
  phase('Spec')
  const spec = await runAgent(
    `Decompose this feature into an ordered, minimal list of implementation tasks across the detected repos.
Feature: ${feature}
Repos: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path })))}

Investigation:
- Relevant files: ${invFiles.map((f) => `${f.path}${f.repo ? ` [${f.repo}]` : ''} (${f.why})`).slice(0, 40).join('; ') || 'none'}
- Conventions: ${invConventions.join('; ') || 'none noted'}
- Risks: ${invRisks.join('; ') || 'none noted'}
- Already implemented (do NOT recreate 'complete' pieces): ${existingImpl.map((e) => `${e.what} [${e.status}]${e.path ? ` @${e.path}` : ''}`).join('; ') || 'nothing pre-existing'}
- User journey: entry ${(userJourney && userJourney.entryPoints || []).join(', ') || '?'} → expected ${(userJourney && userJourney.expectedEndState) || '?'}
- Broken links the feature depends on (each MUST get a task that makes it resolve): ${brokenLinks.map((b) => `${b.target} (${b.reason})`).join('; ') || 'none'}
${briefRules.length ? `- Business rules from ${brief.path} (each must be enforced; cite its BR id in the AC that proves it, e.g. "AC-2 (BR-31): ..."): ${briefRules.join('; ')}
` : ''}
Also write acceptanceCriteria ("AC-n: " + EARS "WHEN <trigger> THE SYSTEM SHALL <response>" or Given/When/Then, one observable outcome each) and mustNotChange ("MNC-n: " + existing behavior on the touched code paths that must remain identical). When authorization per role, a latency budget, an accessibility level, or personal-data handling is at stake, also write nfrs ("NFR-n: <attribute>: <requirement with a measurable target>"); otherwise leave nfrs empty.
Each task needs: integer id, title, the "stack" it targets (one of ${repos.map((r) => r.stack).join('/')}), likely files, an approach, a one-line verify criterion, and covers (the AC/MNC/NFR ids it satisfies). Order so each builds on the previous; group backend-before-frontend where the frontend consumes new backend work.
Skip tasks for pieces already marked 'complete'. Every broken link above MUST be covered by a task that makes the target resolve end-to-end — a feature that ends at a 404/missing target is not shippable.`,
    { phase: 'Spec', schema: SPEC_SCHEMA, agentType: 'code-explorer', ...MODELS.spec }
  )
  tasks = (spec && spec.tasks) || []
  acceptanceCriteria = (spec && spec.acceptanceCriteria) || []
  mustNotChange = (spec && spec.mustNotChange) || []
  nfrs = (spec && spec.nfrs) || []
  if (!tasks.length) {
    log('Spec produced no tasks.')
    return { feature, project, investigation, error: 'no tasks generated' }
  }
  log(`Spec: ${tasks.length} task(s)`)

  const gatesDoc = repos
    .map((r) => `${r.role} (${r.stack}): ${(r.gateCommands || []).map((g) => g.command).join(', ') || 'detected lint/test tooling'}`)
    .join(' | ')
  const persisted = await runAgent(
    `Persist this feature spec to disk following the project's spec conventions, then return the created paths. This is file I/O — no framework code.

Spec folder (never compute "highest number + 1" — parallel sessions collide):
- SLUG = lowercase-hyphenated, <= 40 chars, from the title.
- ${ticket ? `Ticket key "${ticket}": BASE="spec-${ticket}-$SLUG" (keep the key's case).` : 'No ticket: BASE="spec-$(date +%Y%m%d-%H%M)-$SLUG" — timestamp from the shell.'}
- Create atomically: mkdir -p .ai/specs; DIR=.ai/specs/$BASE; n=2; until mkdir "$DIR" 2>/dev/null; do DIR=.ai/specs/$BASE-$n; n=$((n+1)); done
- specId = the folder name.

Write (lowercase names, no AI-marker/changelog comments):
1. spec-lite.md — YAML frontmatter: id (folder name), title, type: feature, size, priority: P2, status: in-progress, ticket: ${ticket || '<blank>'}, stakeholders: [], approved_by: <blank>, approved_at: <blank> (<blank> = key written with no value, e.g. "approved_by:"; never the literal text "<blank>", "(empty)" or "none"), created: $(date +%Y-%m-%d), stacks, slice: ${slice || '<blank>'}, brs: [${briefRules.map((r) => String(r).split(':')[0].trim()).join(', ')}]. Sections: Summary; Context (name ${brief ? brief.path : 'the product brief'} as the rules' source when there is one); Scope (In/Out); Must NOT change; Acceptance criteria;${nfrs.length ? ' Quality attributes (a table: | ID | Attribute | Requirement | Verified by |, one row per NFR);' : ''} Boundaries (Always / Ask first / Never — derive from the conventions and risks); Technical context (relevant files, approach, repos); Open questions (the investigation's open questions as unchecked items${briefDraft && briefRules.length ? `, plus one unchecked "Assumption: <BR-nn> is an unvalidated draft rule (${brief.path}, owner ${brief.owner || 'unnamed'})" per brief rule cited` : ''}); footer "Next: ship-feature {spec:\\"<specId>\\"}".${slice && brief ? `
3. In the backlog.md next to ${brief.path}, set slice ${slice}'s Spec field to the specId and its Status to specced. Change nothing else in that file.` : ''}
2. tasks.md — ordered checklist "- [ ] N. {title} ({stack})" each with a "Covers: ..." line and nested "- [ ] N.x **Verify**: {criterion}"; then a "## Traceability" heading followed by a table (| ID | Criterion (short) | Verified by | Kind (test/manual) | Task |) with one row per AC, MNC and NFR; then "Verification gates" listing the ACTUAL detected gates (do NOT hardcode commands): ${gatesDoc}; then "Done when".

Feature: ${feature}
Repos: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path })))}
Relevant files: ${JSON.stringify(invFiles.slice(0, 20))}
Acceptance criteria: ${JSON.stringify(acceptanceCriteria)}
Must NOT change: ${JSON.stringify(mustNotChange)}
Quality attributes: ${JSON.stringify(nfrs)}
Open questions: ${JSON.stringify(investigations.flatMap((i) => i.openQuestions || []))}
Tasks: ${JSON.stringify(tasks)}

Return specId (the folder name), specFolder (relative path), and the tasks you wrote (done:false, keep their stack and covers).`,
    { phase: 'Spec', schema: SPEC_FILE_SCHEMA, agentType: WRITER_AGENT, ...MODELS.spec }
  )
  if (persisted && persisted.specFolder) {
    specId = persisted.specId
    specFolder = persisted.specFolder
    log(`Spec persisted: ${specId} → ${specFolder}`)
  } else {
    log('Spec persistence skipped (write failed) — continuing in-memory.')
  }
}

const specLabel = specId ? `spec ${specId}` : (feature || 'feature')
const specTrackNote = specFolder
  ? `When done, tick this task complete in ${specFolder}/tasks.md (its "- [ ] N." and Verify subitem → "- [x]"). Do not alter other tasks.`
  : ''

// --- Build (serial; right specialist + repo per task; budget-guarded) ----
const built = []
const failedTasks = []
async function buildTasks(list) {
  for (const task of list) {
    if (budget.total && budget.remaining() < 80_000) {
      log(`Budget low (${Math.round(budget.remaining() / 1000)}k left) — stopping build at task ${task.id}.`)
      list.filter((t) => t.id >= task.id).forEach((t) => failedTasks.push(t.id))
      break
    }
    const repo = repoForStack(task.stack)
    const priorContext = built.length ? `Already completed: ${built.map((b) => b.summary).join('; ')}` : 'This is the first task.'
    // write-spec makes task 1 of a refactor spec the characterization task.
    const characterization = specType === 'refactor' && (task.id === 1 || /characteri[sz]ation/i.test(task.title || ''))
    const method = specType !== 'refactor'
      ? 'using TDD (failing test first, then make it pass)'
      : characterization
        ? 'as the characterization task of a behavior-preserving refactor: write tests that pin TODAY\'s behavior for each MNC item it covers and run them against the unchanged code — they must PASS (green first, no RED step). A characterization test that fails means the code does not do what the MNC item says: stop, set completed=false, and report the mismatch. Change no production code in this task'
        : 'as a step of a behavior-preserving refactor: there is no RED step. Restructure the code with the characterization (MNC guard) tests green before and after, and never edit them. A structural AC (e.g. "X has no pricing logic") may get an architecture test, which fails first as usual'
    const result = await runAgent(
      `Implement this task ${method}. Work in the ${repo.role} repo (${repo.stack}) at "${repo.path}" — cd there.
Task ${task.id}: ${task.title}
Approach: ${task.approach || '(derive from the spec and surrounding code)'}
${task.verify ? `Verify: ${task.verify}` : ''}
${(task.covers || []).length ? `Covers: ${task.covers.join(', ')} — name the test after the criterion so the tasks.md Traceability row can point at it.` : ''}
${task.files && task.files.length ? `Likely files: ${task.files.join(', ')}` : ''}
${priorContext}
${mustNotChange.length ? `Must NOT change (keep identical; do not edit their guard tests): ${mustNotChange.join('; ')}` : ''}
${nfrs.length ? `Quality attributes (an NFR this task covers is built against like an AC: a test per role for authorization, a measured check for a latency budget, an axe assertion for accessibility): ${nfrs.join('; ')}` : ''}

Conventions: ${(repo.conventions || invConventions).join('; ') || 'match surrounding style'}
Skills to consult: ${skillNamesFor(repo.stack).join(', ') || '(none declared)'}
Standards: no changelog/AI-marker comments, lowercase doc filenames, match surrounding style.
${specTrackNote}
Set completed=true only if the task is fully done with a passing test. Return what you changed (full repo-relative paths).`,
      { label: `build:t${task.id}`, phase: 'Build', schema: BUILD_SCHEMA, agentType: agentForStack(task.stack), ...MODELS.build }
    )
    if (result && result.completed !== false) built.push({ id: task.id, ...result })
    else failedTasks.push(task.id)
  }
}

// --- Gates (per repo, parallel; dynamic tooling; auto-fix loop) ----------
// With split repos and contract-sync installed, API drift is a gate like any other.
function contractSyncInstructions() {
  const routeList = routeListCommandFor(backendRepo.stack)
  return `Run the contract-sync gate, which compares the backend's routes with the endpoints the frontend calls.
Command: ${contractSync.command} — run it in "${contractSync.repo}".${routeList ? ` If it needs the backend route list and is not configured to fetch it, generate it with \`${routeList} > /tmp/route-list.json\` in "${backendRepo.path}" and pass --routes-file /tmp/route-list.json.` : ''}
Exit 0 = pass. Exit 1 = drift = fail: put every finding (missing-in-backend, method-mismatch, and unused-by-frontend when strict) in details. Exit 2 = bad input = unreachable, NEVER pass.
Report exactly one gate named "contract-sync"; set repo="${contractSync.repo}" and allPassed accordingly. Do not fix anything here.`
}
async function runGates() {
  const jobs = repos.map((r) => () => runRepoGates(r, gateInstructionsFor, { label: `gates:${r.role}`, phase: 'Gates', schema: GATES_SCHEMA, ...MODELS.gatesFix }))
  if (contractSync && (isUntrustedStack(backendRepo.stack) || isUntrustedStack(frontendRepo.stack))) {
    jobs.push(async () => ({ repo: contractSync.repo, gates: [{ name: 'contract-sync', status: 'unreachable', details: NOT_RUN_UNTRUSTED }], allPassed: false }))
  } else if (contractSync && (!contractSync.command || backendRepo.declinedStack || frontendRepo.declinedStack)) {
    const details = contractSync.command ? `${NOT_RUN_DECLINED}: a repo's stack comes from a declined manifest)` : `${NOT_RUN_DECLINED}: the contract-sync command Detect reported is not allowlisted)`
    jobs.push(async () => ({ repo: contractSync.repo, gates: [{ name: 'contract-sync', status: 'unreachable', details }], allPassed: false }))
  } else if (contractSync) {
    jobs.push(() => runAgent(contractSyncInstructions(), { label: 'gates:contract-sync', phase: 'Gates', schema: GATES_SCHEMA, ...MODELS.gatesFix }))
  }
  const results = (await parallel(jobs)).filter(Boolean)
  const allGates = results.flatMap((g) => (g.gates || []).map((x) => ({ ...x, repo: g.repo })))
  return { results, allGates, allPassed: results.length > 0 && results.every((g) => g.allPassed) }
}
async function gatesUntilGreen() {
  let current = await runGates()
  let fixRounds = 0
  while (!current.allPassed && fixRounds < 3) {
    const failing = current.allGates.filter(isFixableGate)
    if (!failing.length) {
      log('Gates not all green but nothing actionable to fix — stopping loop.')
      break
    }
    if (budget.total && budget.remaining() < 60_000) {
      log(`Gates failing but budget low (${Math.round(budget.remaining() / 1000)}k left) — stopping fix loop.`)
      break
    }
    fixRounds++
    log(`Gates round ${fixRounds}: fixing ${failing.length} failing gate(s)`)
    // Fix per repo so the right specialist edits the right tree.
    const byRepo = repos.filter((r) => failing.some((f) => f.repo === r.path))
    await parallel(
      (byRepo.length ? byRepo : repos).map((r) => () =>
        runAgent(
          `Quality gates are failing in the ${r.role} repo (${r.stack}) at "${r.path}". cd there. Fix the underlying code (not the gate config); do not suppress errors or weaken assertions.${contractSync ? `
A "contract-sync" failure means the frontend and backend disagree on an endpoint. The backend contract (docs/api/api-contracts.md and the spec) is authoritative: fix the side that deviates from it, and if the backend itself is missing the route, report that instead of inventing a frontend workaround.` : ''}
Failures:
${failing.filter((f) => !f.repo || f.repo === r.path).map((g) => `- ${g.name}: ${g.details || ''}`).join('\n')}`,
          { label: `gates:fix${fixRounds}:${r.role}`, phase: 'Gates', agentType: agentForStack(r.stack), ...MODELS.gatesFix }
        )
      )
    )
    current = await runGates()
  }
  return current
}

// --- Build → Gates → Converge loop ---------------------------------------
// Converge audits the code against the spec and APPENDS gap tasks to tasks.md
// rather than editing code, so every change stays traceable to a task.
let gates = null
let pending = tasks
let convergeRound = 0
const convergeLog = []
let remainingGaps = []
while (true) {
  phase('Build')
  await buildTasks(pending)
  log(`Build: ${built.length}/${tasks.length} task(s) implemented${failedTasks.length ? ` (incomplete: ${failedTasks.join(', ')})` : ''}`)

  phase('Gates')
  gates = await gatesUntilGreen()

  phase('Converge')
  if (!built.length) {
    log('Converge: skipped — nothing was built.')
    break
  }
  if (budget.total && budget.remaining() < 100_000) {
    log(`Converge: skipped — budget low (${Math.round(budget.remaining() / 1000)}k left).`)
    break
  }
  convergeRound++
  const nextId = Math.max(specMaxTaskId, ...tasks.map((t) => t.id || 0)) + 1
  const audit = await runAgent(
    `Audit the implementation against the spec. Do NOT edit any code — your only write is appending gap tasks to tasks.md.
Spec: ${specFolder ? `${specFolder} (read spec-lite.md and tasks.md)` : `in-memory (no spec folder) — feature: ${feature}`}
Acceptance criteria: ${JSON.stringify(acceptanceCriteria)}
Must NOT change: ${JSON.stringify(mustNotChange)}
Quality attributes: ${JSON.stringify(nfrs)}
Tasks: ${JSON.stringify(tasks.map((t) => ({ id: t.id, title: t.title, covers: t.covers || [] })))}
Built so far: ${JSON.stringify(built.map((b) => ({ id: b.id, summary: b.summary, changedFiles: b.changedFiles })))}
Incomplete tasks: ${JSON.stringify(failedTasks)}
Gate status: ${gates.allPassed ? 'green' : 'NOT green'}
${awaitingOwner ? `Out of scope: tasks ${ownerCut.join(', ')} wait for the owner gate "${awaitingOwner}". Do not report their work as gaps, and never add a gap titled "Gate:".\n` : ''}
Read the changed code and its tests. For every AC: is it implemented AND covered by a test (or a manual-test step)? For every MNC: is there a guard proving the behavior is unchanged? For every NFR: is the requirement met and proven by a test or a recorded measurement against its target? For every task: is its Verify criterion actually met? Anything missing, half-done, or untested is a gap.
Report only concrete gaps grounded in the code (not style preferences, not scope creep beyond the spec). Each gap: title, reason (what is missing, with file evidence), stack, files, approach, verify, covers (AC/MNC/NFR ids).
${specFolder ? `If there are gaps, ${awaitingOwner ? `insert them in ${specFolder}/tasks.md directly above the line "- [ ] ${ownerGateId}. ${awaitingOwner}" (never below it: nothing after an unchecked gate can be built)` : `append them to ${specFolder}/tasks.md`} under a "## Phase: Gaps (converge round ${convergeRound})" heading as "- [ ] N. {title} ({stack})" with "Covers:" and a "**Verify**:" subitem, numbering from ${nextId}; set appended=true. Change nothing else. Then return tasksMd: the full text of tasks.md after your edit, every line unchanged.` : 'There is no tasks.md to append to; just return the gaps.'}
List in covered the AC/MNC/NFR ids that are fully implemented and tested.`,
    { phase: 'Converge', label: `converge:r${convergeRound}`, schema: CONVERGE_SCHEMA, ...MODELS.converge }
  )
  const gaps = ((audit && audit.gaps) || []).filter((g) => !String(g.title || '').trim().startsWith('Gate:')).map((g, i) => ({ ...g, id: nextId + i }))
  convergeLog.push({ round: convergeRound, gaps: gaps.map((g) => ({ id: g.id, title: g.title, reason: g.reason })) })
  if (!gaps.length) {
    log(`Converge round ${convergeRound}: no gaps — implementation matches the spec.`)
    break
  }
  if (specFolder) {
    // A gap task below an unchecked gate could never be built by a later run, so the round stops instead.
    const placed = strandedGaps(audit.tasksMd, gaps)
    if (placed.stranded.length) {
      tasks = tasks.concat(gaps)
      remainingGaps = gaps
      log(`Converge round ${convergeRound}: gap task(s) ${placed.stranded.join(', ')} are not buildable in tasks.md (${placed.reason}); none were built. Move them above the first unchecked gate and re-run.`)
      break
    }
  }
  tasks = tasks.concat(gaps)
  if (convergeRound >= CONVERGE_ROUNDS) {
    remainingGaps = gaps
    log(`Converge round ${convergeRound}: ${gaps.length} gap(s) remain after ${CONVERGE_ROUNDS} rounds — left in tasks.md for a human: ${gaps.map((g) => `${g.id}. ${g.title}`).join('; ')}`)
    break
  }
  log(`Converge round ${convergeRound}: ${gaps.length} gap task(s) appended — rebuilding`)
  pending = gaps
}
const partialBuild = built.length !== tasks.length - remainingGaps.length

// --- Visual (Playwright MCP; only when UI changed) ----------------------
phase('Visual')
const allChanged = Array.from(new Set(built.flatMap((b) => b.changedFiles || [])))
const uiChanged = allChanged.filter((f) => /\.(tsx|jsx|html?|s?css|less)$/.test(f))
let visual = null
if (!uiChanged.length) {
  log('Visual: skipped — no UI files changed.')
} else {
  const visualPass = (front, url, files, opts) => runAgent(
    `Run visual tests on the running app with the browser tools described at the end of this prompt (Playwright MCP first). Check each changed page at desktop (1440px) and mobile (390px) widths with browser_resize. Catch theming, UI, UX, responsive, and contrast regressions a unit test cannot.
${front ? `Frontend repo: ${front.role} (${front.stack}) at "${front.path}".` : ''}
Changed UI files: ${files.join(', ')}
App URL: ${appUrlLine(url)}

1. Confirm a dev server is reachable at the URL (try ports 3000/5173/8000). If nothing is reachable, return ran=false with details "${NO_APP_URL}" — do NOT fabricate findings.
2. Open a tab (tabs_create_mcp) and navigate to the affected page(s).
3. Screenshot + inspect: theme correctness (light AND dark), hierarchy, spacing/alignment, broken layout, overflow, UX problems (unreachable controls, missing focus states, illegible text).
4. Resize to ~375px / ~768px / ~1440px and check responsive behavior.
5. Check text/background contrast against WCAG AA.
Do NOT trigger native alert/confirm/prompt dialogs — they freeze the extension. Report concrete findings only, each with area + severity.`,
    { phase: 'Visual', schema: VISUAL_SCHEMA, ...opts, ...MODELS.review }
  )
  if (frontends.targets.length > 1) {
    // Only frontends with changed UI get a pass; the passes share one browser, so they run one at a time.
    const split = frontendChanges(frontends.targets, uiChanged, repos)
    const checked = split.filter((t) => t.files.length)
    const unchanged = split.filter((t) => !t.files.length)
    unchanged.forEach((t) => log(`Visual: ${t.repo.path} skipped — no UI files changed in that repo.`))
    const passes = await sequentialPasses(checked, (t) => visualPass(t.repo, t.url, t.files, { label: `visual:${t.repo.path}` }))
    visual = {
      ran: passes.some((v) => v && v.ran),
      findings: passes.flatMap((v, i) => ((v && v.ran && v.findings) || []).map((f) => ({ ...f, description: `[${checked[i].repo.path}] ${f.description}` }))),
      passes: checked.map((t, i) => ({ repo: t.repo.path, url: t.url, ran: !!(passes[i] && passes[i].ran) }))
        .concat(unchanged.map((t) => ({ repo: t.repo.path, url: t.url, ran: false, status: 'skip', reason: 'no UI files changed in this repo' }))),
    }
  } else {
    visual = await visualPass(frontendRepo, devUrl, uiChanged, {})
  }
  if (visual && visual.ran) log(`Visual: ${(visual.findings || []).length} finding(s)`)
  else if (visual) {
    visual = skipResult(NO_APP_URL)
    log(`Visual: ${NO_APP_URL} — skipped.`)
  } else log('Visual: could not run — skipped.')
}
const visualFindings = (visual && visual.findings) || []

// --- Review (dimensions, each finding adversarially verified) ------------
phase('Review')
const DIMENSIONS = [
  { key: 'correctness', prompt: 'logic errors, edge cases, off-by-one, null handling, incorrect business rules' },
  { key: 'security', prompt: 'auth/authz gaps, injection, mass assignment, sensitive data exposure, missing validation' },
  { key: 'performance', prompt: 'N+1 queries, missing indexes, unbounded loops, unnecessary re-renders, oversized payloads' },
  { key: 'design', prompt: 'layer violations, adherence to the detected stack conventions, dead code' },
]
const changedFiles = allChanged

const reviewed = await pipeline(
  DIMENSIONS,
  (d) =>
    runAgent(
      `Adversarially review the changes for ${specLabel} on the ${d.key} dimension. Look specifically for: ${d.prompt}.
Changed files: ${changedFiles.join(', ') || '(inspect recent git diff across all repos)'}
Question every pattern — do not assume correctness. Report concrete findings only, with file and line where possible.`,
      { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA, ...MODELS.review }
    ),
  (review, dim) =>
    parallel(
      ((review && review.findings) || []).map((f) => () =>
        parallel(
          ['correctness', 'reproducibility', 'severity'].map((lens) => () =>
            runAgent(
              `A reviewer claims a real ${dim.key} issue: "${f.title}" in ${f.file || '?'}${f.line ? ':' + f.line : ''}.
${f.description || ''}
Judge it through the ${lens} lens. Try to REFUTE it — default real=false if you cannot confirm it from the actual code.`,
              { label: `verify:${dim.key}`, phase: 'Review', schema: VERDICT_SCHEMA, ...MODELS.verify }
            )
          )
        ).then((votes) => {
          const present = votes.filter(Boolean)
          const yes = present.filter((v) => v.real).length
          // Confirmed only on a majority of the votes that actually returned.
          const confirmed = present.length > 0 && yes >= Math.ceil(present.length / 2) && yes >= 2
          return { ...f, dimension: dim.key, confirmed }
        })
      )
    )
)

const confirmed = reviewed.flat().filter(Boolean).filter((f) => f.confirmed)
log(`Review: ${confirmed.length} confirmed finding(s)`)

// --- Acceptance: trace the ORIGINAL reported scenario end-to-end ----------
// Guards against "tests pass but the feature still doesn't work" — the build
// can be green while the reported problem (a 404, a dead link) is untouched.
phase('Acceptance')
let acceptance = null
if (!built.length) {
  log('Acceptance: skipped — nothing was built.')
} else {
  const acceptancePass = (pass, opts) => runAgent(
    `Verify the ORIGINAL reported scenario now actually works end-to-end against the code as it stands. Do NOT trust that passing unit tests mean the user-facing problem is fixed — trace the real journey.
Feature / reported problem: ${feature || specLabel}
Repos: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path, tracked: r.tracked })))}
${pass ? `Frontends: ${frontendPasses}. This pass covers only ${pass.repo.path} (${pass.repo.stack}) at ${appUrlLine(pass.url)}: walk the journey in the browser through that frontend; each other frontend gets its own pass.\n` : ''}Entry points: ${(userJourney && userJourney.entryPoints || []).join(', ') || '(derive from the feature description)'}
Expected end state: ${(userJourney && userJourney.expectedEndState) || '(the reported problem no longer occurs)'}
Broken links flagged at investigation: ${brokenLinks.map((b) => b.target).join(', ') || 'none'}
Acceptance criteria: ${JSON.stringify(acceptanceCriteria)}
Must NOT change: ${JSON.stringify(mustNotChange)}
Quality attributes: ${JSON.stringify(nfrs)}
Changed files: ${allChanged.join(', ') || '(inspect git diff)'}

Walk the journey as a real request/user would: from each entry point, follow every hop (route → controller → service → response, or page → redirect → target page) to the expected end state. For each hop record step, expected, actual, ok. A redirect or link whose TARGET does not exist/resolve is ok=false and goes in brokenLinks. Also add one step per acceptance criterion (does the code satisfy it?) one per Must NOT change item (is that behavior still identical? compare against git history for the touched paths), and one per quality attribute (does the code meet it, and which test or measurement shows it?). Set resolved=true ONLY if the full journey reaches the expected end state with no broken hop, every AC and NFR holds, and no MNC behavior changed. If a repo is untracked WIP, say so in reason — it is not a verified deploy target.`,
    { phase: 'Acceptance', schema: ACCEPTANCE_SCHEMA, ...MODELS.acceptance, ...opts }
  )
  if (frontends.targets.length > 1) {
    // One pass per frontend, one at a time (they share one browser); a frontend with no changed files gets a lighter model.
    const split = frontendChanges(frontends.targets, allChanged, repos)
    const results = await sequentialPasses(split, (t) => acceptancePass(t, { label: `acceptance:${t.repo.path}`, ...(t.files.length ? {} : MODELS.acceptanceUnchanged) }))
    acceptance = mergeAcceptancePasses(split, results)
  } else {
    acceptance = await acceptancePass(null, {})
  }
  if (acceptance) {
    log(`Acceptance: ${acceptance.resolved ? 'RESOLVED' : 'NOT resolved'}${(acceptance.brokenLinks || []).length ? ` — broken: ${acceptance.brokenLinks.join(', ')}` : ''}`)
  }
}

// Browser acceptance as a regression test: the journey just traced becomes an
// E2E spec traced to the AC ids, so it is re-checked on every later run. Every
// skip carries status 'skip' and never changes the recommendation.
let e2e = null
const e2eManifest = frontendRepo ? e2eFor(frontendRepo.stack) : null
if (!built.length || !frontendRepo) {
  if (e2eArg) log('E2E: skipped — nothing was built or there is no frontend repo.')
} else if (e2eSkip) {
  e2e = e2eSkip
  log(`E2E: ${e2e.details}`)
} else {
  const slug = specFolder ? specFolder.split('/').filter(Boolean).pop().replace(/^spec-/, '') : null
  const pmEntry = packageManagerFor(frontendRepo, false)
  const e2eRun = pmEntry || !packageManagersFor(frontendRepo.stack).length
    ? `\`${fillPackageManager(e2eManifest.run, pmEntry)}\``
    : `\`${e2eManifest.run}\`, with <pm>/<pmx> filled from the package manager the lockfile names`
  const e2eFile = e2eFileFor(frontendRepo.stack, slug)
  const backendE2e = backendRepo && backendRepo.path !== frontendRepo.path ? e2eBackendFor(backendRepo.stack) : null
  e2e = await runAgent(
    `Turn the acceptance journey below into an E2E regression test in the frontend repo at "${frontendRepo.path}" (cd there${frontendRepo.packageManager ? `; package manager: ${frontendRepo.packageManager}` : ''}).
Skills to consult: ${testSkillNamesFor(frontendRepo.stack).join(', ') || '(none declared)'}.
File: ${e2eFile ? `${e2eFile} — use the test directory ${e2eManifest.configGlob} sets if it differs.` : `a new test file for this feature, placed and named like the existing tests that ${e2eManifest.configGlob} runs.`} Update the file if it exists; never delete existing tests.
Feature: ${specLabel}
Entry points: ${(userJourney && userJourney.entryPoints || []).join(', ') || '(derive from the feature)'}
Expected end state: ${(userJourney && userJourney.expectedEndState) || '(the feature works end to end)'}
Acceptance criteria: ${JSON.stringify(acceptanceCriteria)}
Acceptance trace: ${JSON.stringify(acceptance && acceptance.steps || [])}
App URL: ${appUrlLine(devUrl)}
Rules: ${e2eManifest.convention || 'one test per user-visible acceptance criterion, named with its id'}${e2eManifest.seed ? `
Test data: ${e2eManifest.seed}.` : ''}${backendE2e ? `
Backend (${backendRepo.stack} at "${backendRepo.path}"): ${backendE2e.convention}${backendE2e.seed ? `. Its test data: ${backendE2e.seed}` : ''}.` : ''}
Then run it: ${e2eRun}. Report ran=false with the reason if the config lacks a way to start the app or the environment does not come up — never report a test you could not run as passed.${specFolder ? `
Finally, in ${specFolder}/tasks.md set the Traceability "Verified by" cell of each AC the file covers to "<file>::<test name>" (leave rows already pointing at a passing test alone).` : ''}`,
    { label: 'acceptance:e2e', phase: 'Acceptance', schema: E2E_SCHEMA, agentType: TEST_AGENT, ...MODELS.e2e }
  )
  if (e2e) log(`E2E: ${e2e.written ? e2e.path || 'written' : 'not written'} — ${e2e.ran ? (e2e.passed ? 'passing' : 'FAILING') : `not run${e2e.details ? ` (${e2e.details})` : ''}`}`)
}
const e2eFailed = !!(e2e && e2e.ran && !e2e.passed)
const acceptanceResolved = !!(acceptance && acceptance.resolved) && !e2eFailed

// --- Docs ---------------------------------------------------------------
phase('Docs')
let docs = null
const blockingFindings = confirmed.filter((f) => f.severity === 'critical')
if (!built.length) {
  log('Docs: skipped — nothing was built.')
} else if (partialBuild) {
  log('Docs: skipped — build incomplete; docs would describe unfinished behavior.')
} else if (blockingFindings.length) {
  log(`Docs: skipped — ${blockingFindings.length} critical finding(s) unresolved.`)
} else if (acceptance && !acceptance.resolved) {
  log('Docs: skipped — acceptance not met; docs would describe a feature that does not work end-to-end.')
} else {
  const docTargets = docsToUpdate.length
    ? docsToUpdate.map((d) => `- ${d.path}: ${d.reason}`).join('\n')
    : '(none pre-identified — discover affected docs from the changed files)'
  docs = await runAgent(
    `The work below shipped. Update the project's EXISTING documentation across all repos so it reflects the new behavior. Document only what the code actually does now — verify each claim against the implementation.
Feature: ${specLabel}
Repos: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path })))}
Changed files: ${changedFiles.join(', ') || '(inspect recent git diff)'}
Tasks shipped: ${JSON.stringify(built.map((b) => ({ id: b.id, summary: b.summary })))}

Docs flagged during investigation:
${docTargets}

Rules: prefer updating existing docs; new docs only when nothing covers the area; lowercase filenames (except CLAUDE.md/README.md); no AI-marker/changelog comments; don't touch unaffected docs (list them under skipped).`,
    { phase: 'Docs', schema: DOCS_SCHEMA, agentType: WRITER_AGENT, ...MODELS.docs }
  )
  if (docs) log(`Docs: ${(docs.updatedDocs || []).length} updated, ${(docs.newDocs || []).length} new`)
}

// Only an untrusted manifest that a detected repo uses blocks SHIP; the others are reported for information.
const blockingManifests = blockingUntrusted(untrustedManifests, repos)
const notShippable = partialBuild || (gates && !gates.allPassed) || blockingFindings.length || (acceptance && !acceptance.resolved) || e2eFailed || repoWarnings.length || remainingGaps.length || blockingManifests.length

// --- TestPlan: copy-paste manual QA steps for a human --------------------
phase('TestPlan')
let testPlan = null
if (!built.length) {
  log('TestPlan: skipped — nothing was built.')
} else {
  const planPath = specFolder ? `${specFolder}/manual-test.md` : null
  testPlan = await runAgent(
    `Write a concrete, copy-paste manual test plan a human runs to verify this feature by hand — no AI/agent jargon, real values they can paste. Verify each step against the actual implementation; do not invent endpoints or URLs.
Feature: ${feature || specLabel}
Repos: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path, devUrl: r.devUrl })))}
Entry points: ${(userJourney && userJourney.entryPoints || []).join(', ') || '(derive from the feature)'}
Expected end state: ${(userJourney && userJourney.expectedEndState) || '(reported problem no longer occurs)'}
App URL(s): ${appUrlLine(devUrl)}
Acceptance trace: ${JSON.stringify(acceptance && { resolved: acceptance.resolved, steps: acceptance.steps } || 'not run')}
Changed files: ${allChanged.join(', ') || '(inspect git diff)'}

Each step: a precise action (exact URL to open / command to run / button to click with real example data) and the exact expected result (status code, redirect target, on-screen text). Include preconditions (env, seeded data, login) and a rollback note if the change is risky. Cover the happy path AND the originally-reported failing case (it must now pass), plus one step for each acceptance criterion, Must NOT change item, or quality attribute that has no automated test: ${JSON.stringify([...acceptanceCriteria, ...mustNotChange, ...nfrs])}.${specFolder ? ` Then in ${specFolder}/tasks.md fill the Traceability "Verified by" cells that point at manual steps with "manual-test.md#step-N"${notShippable || awaitingOwner ? '' : `, and set status: done in ${specFolder}/spec-lite.md frontmatter${slice ? `, then set slice ${slice}'s Status to shipped in the backlog.md next to the product-brief.md (the repo root or its parent; change nothing else there)` : ''}`}.` : ''}${planPath ? `\n\nWrite the plan to "${planPath}" as markdown (lowercase filename, human-authored tone, no AI-marker comments). Set path to that file.` : '\nReturn the steps inline (no spec folder to write to).'}`,
    { phase: 'TestPlan', schema: TEST_PLAN_SCHEMA, agentType: WRITER_AGENT, ...MODELS.testplan }
  )
  if (testPlan) log(`TestPlan: ${(testPlan.steps || []).length} step(s)${testPlan.path ? ` → ${testPlan.path}` : ''}`)
}

// --- Report -------------------------------------------------------------
phase('Report')
const recommendationHint = blockingManifests.length ? 'BLOCKED (untrusted stack manifest)' : notShippable ? 'FIX-FIRST or BLOCKED' : 'SHIP unless findings say otherwise'
const trustNext = untrustedNext('ship-feature', blockingManifests)
const specName = specFolder ? specFolder.split('/').filter(Boolean).pop() : specId || null
// The report lives next to the spec: the repo that holds .ai/specs/<folder>.
const reportRepo = specFolder
  ? specFolder.replace(/\/?\.ai\/specs\/[^/]+\/?$/, '') || '.'
  : (primaryRepo && primaryRepo.path) || '.'
const reportSlug = specName || ticket || '<slug>'
const report = await runAgent(
  `Write a concise markdown ship report. Sections: Summary, Stack & repos (flag any untracked/WIP repo; add a "Stack overlay" line: ${stackOverlayLine(stackOverlay, untrustedManifests)}), Spec (id + folder), Investigation highlights (key files, risks, pieces already shipped), Tasks completed (note any incomplete: ${failedTasks.join(', ') || 'none'}), Converge (rounds run, gap tasks appended, gaps left unbuilt), Quality gates per repo (pass/fail/skip/unreachable), Visual tests, Acceptance (did the ORIGINAL reported scenario resolve end-to-end? list any broken hop; the E2E regression test written, its AC ids, and whether it passed or could not run), Confirmed review findings (grouped by severity, file:line + one-line fix), Documentation updated, Manual test plan (where it was written + a one-line how-to-run), Recommendation (SHIP / FIX-FIRST / BLOCKED — likely ${recommendationHint}; a partial build, any unreachable gate (contract-sync included), an unresolved acceptance trace, a failing e2e test, unbuilt converge gaps, or building into an untracked WIP repo must NOT be SHIP). End with a "Next" line: when the recommendation is SHIP, "Next: /open-pr --spec=${specName || '<spec id>'} --report=<reportPath>"; otherwise the first fix to make.${trustNext ? ` An untrusted stack manifest means its gates did not run: the recommendation is BLOCKED and the Next line is exactly "${trustNext}"` : ''}
Save the report: in the repo at "${reportRepo}", mkdir -p .ai/reports and write it to .ai/reports/ship-${reportSlug}-$(date +%Y%m%d-%H%M).md${specName || ticket ? '' : ' (<slug> = 2-5 lowercase-hyphenated words naming the feature)'}, taking the timestamp from the shell, never inventing it. Lowercase filename, written as a human maintainer, no AI-marker comments. Write the file after every other section is final, so its modification time is later than the gate runs it records. Return reportPath (the path relative to the current directory, the same path the Next line names) and markdown (the full report).
Feature: ${specLabel}
Stack: ${JSON.stringify(repos.map((r) => ({ role: r.role, stack: r.stack, tracked: r.tracked })))}
Repo warnings: ${JSON.stringify(repoWarnings)}
Stack overlay: ${JSON.stringify({ ...stackOverlay, untrusted: untrustedManifests })}
Spec: ${JSON.stringify({ specId, specFolder })}
Build: ${built.length}/${tasks.length} (incomplete: ${JSON.stringify(failedTasks)})${awaitingOwner ? `\nAwaiting owner: ${awaitingOwner} (tasks ${ownerCut.join(', ')} not built; say so under Tasks completed)` : ''}
Converge: ${JSON.stringify({ rounds: convergeRound, log: convergeLog, remainingGaps: remainingGaps.map((g) => `${g.id}. ${g.title}`) })}
Investigation: ${JSON.stringify({ relevantFiles: invFiles.slice(0, 12), risks: invRisks, existingImplementation: existingImpl })}
Gates: ${JSON.stringify(gates.allGates)}
Visual: ${JSON.stringify(visual)}
Acceptance: ${JSON.stringify(acceptance)}
E2E: ${JSON.stringify(e2e)}
Confirmed findings: ${JSON.stringify(confirmed)}
Docs: ${JSON.stringify(docs)}
Manual test plan: ${JSON.stringify(testPlan)}`,
  { phase: 'Report', schema: REPORT_SCHEMA, ...MODELS.report }
)
const reportPath = (report && report.reportPath) || null
if (reportPath) log(`Report saved: ${reportPath}`)

return {
  feature: feature || null,
  specId,
  specFolder,
  stacks: repos.map((r) => ({ role: r.role, stack: r.stack, path: r.path })),
  crossRepo,
  taskCount: tasks.length,
  built: built.length,
  partialBuild,
  failedTasks,
  awaitingOwner,
  notBuilt: ownerCut,
  convergeRounds: convergeRound,
  remainingGaps: remainingGaps.map((g) => ({ id: g.id, title: g.title, reason: g.reason })),
  gatesPassed: gates ? gates.allPassed : false,
  visualFindings,
  confirmedFindings: confirmed,
  acceptanceResolved,
  acceptance,
  e2e,
  stackOverlay: { ...stackOverlay, untrusted: untrustedManifests },
  next: trustNext || (notShippable ? null : `/open-pr --spec=${specName || '<spec id>'}${reportPath ? ` --report=${reportPath}` : ''}`),
  repoWarnings,
  brokenLinks,
  docsUpdated: docs ? docs.updatedDocs || [] : [],
  manualTestPlan: testPlan ? testPlan.path || testPlan : null,
  reportPath,
  report: report ? report.markdown : null,
}
